func newFeeTier() unsafe.Pointer { return unsafe.Pointer(new(factoring.FeeTier)) }

func newNFeeTier(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]factoring.FeeTier, n)))
}

func ptrFeeTier(p unsafe.Pointer, c int32) any {
	r := (*factoring.FeeTier)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.AgreementID))
	case 4:
		return (*int64)(unsafe.Pointer(&r.DaysFrom))
	case 5:
		return (**int64)(unsafe.Pointer(&r.DaysTo))
	case 6:
		return (*int64)(unsafe.Pointer(&r.RateBP))
	case 7:
		return &r.FlatMinor
	}
	return nil
}

func valueFeeTier(p unsafe.Pointer, c int32) any {
	r := (*factoring.FeeTier)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.AgreementID)
	case 4:
		return int64(r.DaysFrom)
	case 5:
		if r.DaysTo == nil {
			return nil
		}
		return int64(*r.DaysTo)
	case 6:
		return int64(r.RateBP)
	case 7:
		return r.FlatMinor
	}
	return nil
}

