func newNoa() unsafe.Pointer { return unsafe.Pointer(new(factoring.Noa)) }

func newNNoa(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]factoring.Noa, n))) }

func ptrNoa(p unsafe.Pointer, c int32) any {
	r := (*factoring.Noa)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.CustomerID))
	case 4:
		return (*string)(unsafe.Pointer(&r.FactoringCompanyID))
	case 5:
		return (*string)(unsafe.Pointer(&r.Status))
	case 6:
		return &r.SentAt
	case 7:
		return &r.SentTo
	case 8:
		return &r.AcknowledgedAt
	case 9:
		return (*string)(unsafe.Pointer(&r.SignedDocumentID))
	case 10:
		return &r.ExpiresAt
	case 11:
		return &r.ExpiryWarnedAt
	case 12:
		return &r.ReleasedAt
	case 13:
		return &r.ReleaseReason
	case 14:
		return &r.Notes
	case 15:
		return &r.Version
	case 16:
		return &r.CreatedAt
	case 17:
		return &r.UpdatedAt
	}
	return nil
}

func valueNoa(p unsafe.Pointer, c int32) any {
	r := (*factoring.Noa)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.CustomerID)
	case 4:
		return string(r.FactoringCompanyID)
	case 5:
		return string(r.Status)
	case 6:
		if r.SentAt == nil {
			return nil
		}
		return *r.SentAt
	case 7:
		if r.SentTo == "" {
			return nil
		}
		return r.SentTo
	case 8:
		if r.AcknowledgedAt == nil {
			return nil
		}
		return *r.AcknowledgedAt
	case 9:
		if r.SignedDocumentID == "" {
			return nil
		}
		return string(r.SignedDocumentID)
	case 10:
		if r.ExpiresAt == nil {
			return nil
		}
		return *r.ExpiresAt
	case 11:
		if r.ExpiryWarnedAt == nil {
			return nil
		}
		return *r.ExpiryWarnedAt
	case 12:
		if r.ReleasedAt == nil {
			return nil
		}
		return *r.ReleasedAt
	case 13:
		if r.ReleaseReason == "" {
			return nil
		}
		return r.ReleaseReason
	case 14:
		if r.Notes == "" {
			return nil
		}
		return r.Notes
	case 15:
		return r.Version
	case 16:
		return r.CreatedAt
	case 17:
		return r.UpdatedAt
	}
	return nil
}

func attachNoa(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*factoring.Noa)(p)
	switch rel {
	case 0:
		r.Customer = (*customer.Customer)(child)
	case 1:
		r.FactoringCompany = (*factoringcompany.FactoringCompany)(child)
	}
}

func beforeCreateNoa(ctx context.Context, p unsafe.Pointer) error {
	return (*factoring.Noa)(p).BeforeCreate(ctx)
}

func init() {
	agreementsTable.Relations[0].Target = factoringcompanydb.FactoringCompaniesSchema()
	agreementsTable.Relations[1].Target = FeeTiersSchema()
	agreementsTable.Relations[2].Target = documenttypedb.DocumentTypesSchema()
	agreementDocumentTypesTable.Relations[0].Target = AgreementsSchema()
	agreementDocumentTypesTable.Relations[1].Target = documenttypedb.DocumentTypesSchema()
	noasTable.Relations[0].Target = customerdb.CustomersSchema()
	noasTable.Relations[1].Target = factoringcompanydb.FactoringCompaniesSchema()
}

